import csv
ts_temp = "aa94e675-0b70-525d-8004-da58b0480399"
ts_sp = "7bf711cc-b11d-57c7-853c-a96bf1f3b2bc"

data = {ts_temp: {}, ts_sp: {}}
with open(VALUES_CSV) as f:
    rdr = csv.reader(f)
    next(rdr)
    for tid, ts, val in rdr:
        if tid in data:
            try:
                data[tid][ts] = float(val)
            except:
                pass

def mean_dev(date):
    devs = []
    for ts, tval in data[ts_temp].items():
        d = ts[:10]
        h = int(ts[11:13])
        if d == date and 8 <= h <= 18 and ts in data[ts_sp]:
            devs.append(tval - data[ts_sp][ts])
    return sum(devs)/len(devs), len(devs)

